import React, { useState } from "react";
import { HiChevronLeft, HiChevronRight, HiX } from "react-icons/hi";

const ImageCarousel = ({ image, allImages, setIsRendered }) => {
  const [currentIndex, setCurrentIndex] = useState(image.index ?? 0);

  const prevPhoto = () => {
    const nextImg =
      currentIndex === 0 ? allImages.length - 1 : currentIndex - 1;
    setCurrentIndex(nextImg);
  };

  const nextPhoto = () => {
    const prevImg =
      currentIndex === allImages.length - 1 ? 0 : currentIndex + 1;
    setCurrentIndex(prevImg);
  };

  return (
    <div className="fixed inset-0 z-[60] flex items-center justify-center bg-stone-950/70 px-4 py-6 backdrop-blur-md sm:px-6">
      <div className="w-full max-w-6xl border border-stone-200 bg-white/95 p-3 shadow-[0_24px_70px_rgba(15,23,42,0.18)] sm:p-5">
        <div className="relative overflow-hidden">
          <img
            src={allImages[currentIndex].img}
            alt={`${allImages[currentIndex].type} view`}
            className="h-[78vh] w-full object-cover"
          />

          <button
            type="button"
            onClick={() => setIsRendered(false)}
            className="absolute right-4 top-4 rounded-full border border-stone-200 bg-white/80 p-2 text-stone-700 backdrop-blur"
            aria-label="Close gallery view"
          >
            <HiX size={22} />
          </button>

          <div className="absolute inset-x-0 bottom-0 flex flex-col gap-4 bg-gradient-to-t from-black/90 via-black/40 to-transparent p-6 sm:flex-row sm:items-end sm:justify-between sm:p-8">
            <div>
              <p className="text-xs uppercase tracking-[0.35em] text-amber-600">
                Featured view
              </p>
              <h3 className="mt-2 text-xl font-semibold text-stone-900">
                {allImages[currentIndex].type}
              </h3>
            </div>
            <div className="flex items-center gap-3">
              <button
                type="button"
                onClick={prevPhoto}
                className="rounded-full border border-white/20 bg-white/10 p-2 text-white backdrop-blur"
                aria-label="Previous image"
              >
                <HiChevronLeft size={22} />
              </button>
              <button
                type="button"
                onClick={nextPhoto}
                className="rounded-full border border-white/20 bg-white/10 p-2 text-white backdrop-blur"
                aria-label="Next image"
              >
                <HiChevronRight size={22} />
              </button>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default ImageCarousel;
